package com.mendes.scheduling_platform.platform; import com.mendes.scheduling_platform.exception.BusinessException; import com.mendes.scheduling_platform.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/platform/auth") public class PlatformAuthController { private final PlatformAdminRepository admins; private final PasswordEncoder encoder; private final JwtService jwt; public PlatformAuthController(PlatformAdminRepository a,PasswordEncoder e,JwtService j){admins=a;encoder=e;jwt=j;} public record Login(@Email @NotBlank String email,@NotBlank String password){} public record Token(String token,String type){} @PostMapping("/login") Token login(@Valid @RequestBody Login l){PlatformAdmin a=admins.findByEmailIgnoreCase(l.email()).filter(x->encoder.matches(l.password(),x.getPassword())).orElseThrow(()->new BusinessException("Credenciais inválidas")); return new Token(jwt.issue(a.getEmail(),null,"PLATFORM_ADMIN",true),"Bearer");} }
